import{_ as n,C as a,o as l,c as s,E as t,a2 as i}from"./chunks/framework.IIAdu7fg.js";const d="/joinwell52/assets/execution-boundaries-20261028/missing-page-still-readable.figure.zh.svg",_=JSON.parse('{"title":"聊天记录缺了一页，AI 恢复工作后会知道吗？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"聊天记录缺了一页，AI 恢复工作后会知道吗？","date":"2026-10-28","published_date":"2026-10-28","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"聊天记录缺了一页，AI 恢复工作后会知道吗？","summary":"一次恢复测试：删除中间事件后，剩下的记录还能读，但原始序号必须留下空洞。可继续工作，不等于历史完整。","cover":"/assets/execution-boundaries-20261028/missing-page-still-readable.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码；上游缺页回归测试在本机的修复前后对照","pageClass":"six-governance-article"},"headers":[],"relativePath":"zh/research/2026-10-28-missing-page-still-readable.md","filePath":"zh/research/2026-10-28-missing-page-still-readable.md","lastUpdated":null}'),c={name:"zh/research/2026-10-28-missing-page-still-readable.md"};function p(h,e,g,b,u,m){const r=a("ArticleCover"),o=a("ArticleTableScroll");return l(),s("div",null,[t(r,{image:"/assets/execution-boundaries-20261028/missing-page-still-readable.cover-v1.png",kicker:"开源工程观察 · 对照实验",title:"聊天记录缺了一页，AI 恢复工作后会知道吗？",summary:"一次恢复测试：删除中间事件后，剩下的记录还能读，但原始序号必须留下空洞。可继续工作，不等于历史完整。",version:"2026-10-28",languageHref:"/en/research/2026-10-28-missing-page-still-readable",languageLabel:"English"}),t(o,{language:"zh"}),e[0]||(e[0]=i('<h1 id="聊天记录缺了一页-ai-恢复工作后会知道吗" tabindex="-1">聊天记录缺了一页，AI 恢复工作后会知道吗？ <a class="header-anchor" href="#聊天记录缺了一页-ai-恢复工作后会知道吗" aria-label="Permalink to &quot;聊天记录缺了一页，AI 恢复工作后会知道吗？&quot;">​</a></h1><p>一本工作日志有四页。第二页丢了。你当然希望系统还能翻到第三、第四页，继续找到已经完成的工作；但你也希望它明白，中间有一页不见了。</p><p>长期运行的 AI 助手也是如此。它依赖事件记录恢复上下文。如果读取程序遇到缺页就停，后面的有效记录会一起消失；如果悄悄把幸存页重新排成整齐的 1、2、3 页，使用者又可能误以为历史从未断过。</p><h2 id="为什么会研究这一条" tabindex="-1">为什么会研究这一条 <a class="header-anchor" href="#为什么会研究这一条" aria-label="Permalink to &quot;为什么会研究这一条&quot;">​</a></h2><p>10 月 28 日的<a href="https://joinwell52-ai.github.io/joinwell52/zh/runtime/daily-intelligence/2026-10-28" target="_blank" rel="noreferrer">工程动态</a>里，<a href="https://github.com/OpenHands/software-agent-sdk/pull/6197" target="_blank" rel="noreferrer">OpenHands SDK 的 PR #6197</a>修复事件文件丢失后的加载行为。我们关心的不是“能不能打开日志”这个单一指标，而是两个条件能否同时成立：<strong>恢复后继续读到幸存事件；缺失事实仍能被辨认。</strong></p><p>这个问题可以直接构造：写四条事件，删掉中间一个文件，再重新载入。于是我们使用上游仓库的 <code>InMemoryFileStore</code> 测试，把同一组回归用例放到修复前后运行。它模拟文件丢失，不是人为改写真实用户对话。</p><h2 id="缺了第-2-页之后-余下的页去哪了" tabindex="-1">缺了第 2 页之后，余下的页去哪了 <a class="header-anchor" href="#缺了第-2-页之后-余下的页去哪了" aria-label="Permalink to &quot;缺了第 2 页之后，余下的页去哪了&quot;">​</a></h2><p>我们固定修复前源码 <a href="https://github.com/OpenHands/software-agent-sdk/tree/acd96e6fa424c02432304395b9208f99be24b54d" target="_blank" rel="noreferrer"><code>acd96e6f</code></a> 和合并版 <a href="https://github.com/OpenHands/software-agent-sdk/tree/ded5fa5e76ff9b7b4ff622a8df2ed20335e10652" target="_blank" rel="noreferrer"><code>ded5fa5e</code></a>。测试涵盖中间文件丢失、首项丢失、原始序号是否被复用、缺失父事件时的路径，以及警告是否重复刷屏，总计五个参数化用例。</p><table tabindex="0"><thead><tr><th>对照</th><th>五个用例</th><th>我们实际看到的差别</th></tr></thead><tbody><tr><td>修复前</td><td><strong>5/5 未通过</strong></td><td>中间文件缺失时，后续幸存事件没有进入索引；沿父链查找也会失败。</td></tr><tr><td>合并版</td><td><strong>5/5 通过</strong></td><td>幸存事件继续可读，原始位置的空洞被保留并报告，新增事件不占用旧序号。</td></tr></tbody></table><p>最容易看懂的是四条事件的序号。原来是 <code>0、1、2、3</code>；删除序号 <code>1</code> 后，屏幕上可读的三条可以按 <code>0、1、2</code> 依次展示，但它们在磁盘上的原始序号仍是 <code>0、2、3</code>。下一条新事件拿到 <code>4</code>，而不是填回 <code>1</code>。这样，“方便展示的第几条”与“原来发生在什么位置”不会互相冒充。</p><p><img src="'+d+'" alt="四条事件丢失一条后，幸存记录继续可读，原始序号仍有缺口"></p><p><em>图：测试中的序号变化。展示索引变密，磁盘序号保留缺口；图示不代表丢失内容被找回。</em></p><p>在另一组测试里，如果一条事件指向已经丢失的父事件，新版会有界地把幸存记录接回可见的早先事件，并给出警告；相同缺口不会每次遍历都重复告警。它让恢复流程可用，同时提醒读者：<strong>接回的是路径，不是遗失的事实。</strong></p><h2 id="能继续-是一种能力-完整-是一种证据" tabindex="-1">“能继续”是一种能力，“完整”是一种证据 <a class="header-anchor" href="#能继续-是一种能力-完整-是一种证据" aria-label="Permalink to &quot;“能继续”是一种能力，“完整”是一种证据&quot;">​</a></h2><p>本轮对照支持的判断很有限，也正因如此有用：在这些模拟缺页场景中，修复版让可读性和缺口标识一起保留下来。它没有证明损坏的文件被恢复，也没有证明真实磁盘、并发写入或所有部署版本都有同样行为。PR 已合并，我们没有核验具体正式发行版。</p><p>这也给长期 Agent 一个更难的问题：当历史缺了一页，上层负责验收的 Agent 会不会收到“这条证据链不完整”的信息？如果它只看到一条可以继续阅读的链，可能把恢复能力误当成事实完整性。本轮测试没有验证这个上层传播；它是从实验结果自然引出的下一步。</p><p>普通读者也可以给出有价值的反馈：你更希望助手在日志损坏时直接停下，还是先显示可恢复的部分，同时明确标出缺失位置？这个选择会因任务重要性而变，但缺失事实应始终可见。</p><p>固定版本、命令和边界见<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-28-execution-boundaries/00-report.md" target="_blank" rel="noreferrer">公开实验报告</a>。这是<strong>上游缺页回归测试在本机的前后源码对照</strong>，不是线上数据丢失事件。<a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">研究仓库</a></p>',18))])}const A=n(c,[["render",p]]);export{_ as __pageData,A as default};
